//! `ips_calib`: extrinsic calibration of every IPS camera from the detectors'
//! marker stream. The binary is `src/main.rs`; the pieces it is built from live
//! here so the integration tests can reach them.

// sb-generated zenoh subscriber for `ros2/custom/MarkerDetections`. Do not edit,
// `sb install .` regenerates it. Only its `TopicOverrides::key_expr()` is used, to
// render the `ips_detect-$*` fan-in key; its `try_recv_latest` keeps one sample
// and would drop the other cameras' frames, so main declares its own subscriber.
// The allow covers one lint in the generated code (`e.into()` to the same type).
#[path = "../swarmbotix_io/subscribers/markers.rs"]
#[allow(clippy::useless_conversion)]
pub mod markers_sub;

// prost types for `messages/custom/{MarkerDetections,CubePoses}.proto`
// (package `swarmbotix.custom`): Vec3, Quat, MarkerDetection, MarkerDetections,
// Mat3, CubePose, CubePoses. Generated by build.rs.
pub mod msgs {
    include!(concat!(env!("OUT_DIR"), "/swarmbotix.custom.rs"));
}

// sb-generated iceoryx2 subscriber for `ros2/sensor_msgs/Image1280x1024`. Do
// not edit, `sb install .` regenerates it. Its baked default key is this
// module's own; `images` overrides `full` with each camera publisher's key.
#[path = "../swarmbotix_io/subscribers/image.rs"]
pub mod image;

pub mod accumulate;
pub mod board;
pub mod calibrate;
pub mod fit;
pub mod headless;
pub mod images;
pub mod setup;
pub mod ui;
pub mod writer;

// The window: OpenCV drawing and the interactive run. Behind the `ui` feature.
#[cfg(feature = "ui")]
pub mod mosaic;
#[cfg(feature = "ui")]
pub mod session;
